                CHECK(quantity_remaining >= 0 AND quantity_remaining <= quantity_original),
              unit_cost DECIMAL(15,4) NOT NULL DEFAULT 0,
              received_date DATE NOT NULL${optionalDefs.length ? ',\n              ' + optionalDefs.join(',\n              ') : ''}
          );
        `);
        // Column-aware copy
